        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('subscription.subscriptions') AND c.contype = 'f' AND a.attname = 'plan_id'
    ) THEN
        ALTER TABLE subscription.subscriptions ADD CONSTRAINT fk_subscriptions_plan_id FOREIGN KEY (plan_id) REFERENCES subscription.subscription_plans (id) NOT VALID;
        BEGIN
            ALTER TABLE subscription.subscriptions VALIDATE CONSTRAINT fk_subscriptions_plan_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_subscriptions_plan_id left NOT VALID: stored rows of subscription.subscriptions reference missing rows';
        END;
    END IF;
END $$;

